import AxeBuilder from '@axe-core/playwright';
import { expect, test } from '@playwright/test';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  type AxeViolationLike,
  filterGated,
  newViolationsMessage,
  ratchet,
